import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Gelöschte Entitäten","description":"","frontmatter":{"title":"Gelöschte Entitäten","covers":{"screens":["SCR-068"],"stories":["US-074"]}},"headers":[],"relativePath":"de/usage/deleted-entities.md","filePath":"de/usage/deleted-entities.md"}`),a={name:`de/usage/deleted-entities.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="geloschte-entitaten" tabindex="-1">Gelöschte Entitäten <a class="header-anchor" href="#geloschte-entitaten" aria-label="Permalink to “Gelöschte Entitäten”">​</a></h1><p>Wenn du eine Entität aus dem Repository löschst (zum Beispiel mit <em>Aus Repository löschen</em> auf der Zeichenfläche eines <a href="./diagrams#the-canvas">Diagramms</a>), entfernt OEA sie nicht: Die Entität, ihre Kinder und deren Verbindungen werden als gelöscht markiert und können wiederhergestellt werden. Die Seite <em>Gelöschte Entitäten</em> listet sie auf. Sie braucht die Berechtigung <code>entity:restore</code> (Rolle <code>enterprise-architect</code>); ohne sie hat die Kopfzeile keinen Eintrag <em>Gelöschte Entitäten</em>, und die Seite zeigt <em>Keine Berechtigung</em>.</p><h2 id="geloschte-entitaten-finden" tabindex="-1">Gelöschte Entitäten finden <a class="header-anchor" href="#geloschte-entitaten-finden" aria-label="Permalink to “Gelöschte Entitäten finden”">​</a></h2><p>Wähle in der Kopfzeile <em>Gelöschte Entitäten</em>. Die Seite listet die gelöschten Entitäten und Verbindungen, die zuletzt gelöschten zuerst. Jeder Eintrag zeigt:</p><ul><li>den Namen und bei einer Verbindung ihre Quelle und ihr Ziel (auch wenn diese selbst gelöscht sind), den Entitätstyp sowie Person und Zeitpunkt des Löschens;</li><li><em>Gelöscht mit …</em> und den Namen einer Entität, wenn der Eintrag mitgenommen wurde, als diese Entität gelöscht wurde, zum Beispiel ein Kind oder eine Verbindung von ihr.</li></ul><p>Gib einen Namensteil in <em>Nach Name filtern</em> ein (bis zu 255 Zeichen; Zeichen wie <code>%</code> und <code>_</code> gelten, wie eingegeben) und wähle einen Entitätstyp, um die Liste einzugrenzen. Die Liste zeigt 50 Einträge auf einmal; wähle <em>Mehr laden</em> für die nächsten. Ohne gelöschte Entität meldet die Seite <em>Keine gelöschten Entitäten.</em></p><h2 id="restore-an-entity" tabindex="-1">Eine Entität wiederherstellen <a class="header-anchor" href="#restore-an-entity" aria-label="Permalink to “Eine Entität wiederherstellen”">​</a></h2><ol><li>Wähle <em>Wiederherstellen</em> an einem Eintrag.</li><li>Bestätige den Dialog. Die Entität kommt zusammen mit dem zurück, was ihre Löschung mitgenommen hat: ihre Kinder und deren Verbindungen, die mit ihr gelöscht wurden.</li></ol><p>Danach nennt ein Hinweis die Entitäten, die wiederhergestellt wurden, und die, die gelöscht geblieben sind. Eine Verbindung bleibt gelöscht, wenn ihr anderer Endpunkt noch gelöscht ist; stelle auch diese Entität wieder her und danach die Verbindung. Ein Element, dessen Elternelement noch gelöscht ist, kommt auf der obersten Ebene zurück, und der Hinweis sagt das.</p><ul><li><strong>Ein einzelner Eintrag:</strong> Ein Eintrag, der mitgenommen wurde, zum Beispiel ein Kind, kann für sich wiederhergestellt werden. Der Dialog nennt die Entität, mit der er gelöscht wurde.</li><li><strong>Eine Verbindung mit gelöschtem Endpunkt:</strong> Sie allein wiederherzustellen wird abgelehnt. Die Seite meldet das; stelle zuerst den Endpunkt wieder her.</li><li><strong>Jemand war schneller:</strong> Wurde die Entität inzwischen wiederhergestellt oder geändert, meldet die Seite das und lädt die Liste neu.</li></ul><p>Das Wiederherstellen ändert keine Version und wird für jede wiederhergestellte Entität als <code>entity.undeleted</code> im Audit-Trail festgehalten.</p><h2 id="geloschte-zeilen-in-einem-katalog" tabindex="-1">Gelöschte Zeilen in einem Katalog <a class="header-anchor" href="#geloschte-zeilen-in-einem-katalog" aria-label="Permalink to “Gelöschte Zeilen in einem Katalog”">​</a></h2><p>Ein Katalog kann gelöschte Zeilen ebenfalls zeigen, mit dem Schalter <em>Gelöschte anzeigen</em> (siehe <a href="./catalogs#show-deleted">Kataloge</a>). <em>Wiederherstellen</em> funktioniert dort genauso.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><code>GET /entities/deleted</code> listet die gelöschten Entitäten und Verbindungen (<code>entity:restore</code>): die zuletzt gelöschten zuerst, dann nach ID. <code>q</code> ist ein Namensteil (höchstens 255 Zeichen), <code>metatypeId</code> ein Entitätstyp, <code>pageSize</code> ist 1 bis 200 (Standard 50) und <code>page</code> beginnt bei 0. Die Antwort enthält <code>nextCursor</code>; sende ihn als <code>cursor</code> zusammen mit <code>page</code> um 1 erhöht, um fortzufahren. Ein Cursor einer anderen Abfrage wird mit 400 abgelehnt, der <code>cursor</code> nennt; andere ungültige Werte beantwortet die API mit 400.</li><li>Jeder Eintrag hat <code>id</code>, <code>name</code>, <code>metatype</code>, <code>isConnection</code>, bei einer Verbindung <code>source</code> und <code>target</code> (<code>id</code> und <code>name</code>), <code>version</code>, <code>deletedAt</code>, <code>deletedBy</code> und <code>deletedWith</code> (<code>id</code> und <code>name</code>, oder <code>null</code> für eine Entität, die für sich gelöscht wurde). Er enthält keine Eigenschaftswerte.</li><li><code>POST /entities/{id}/undelete</code> mit dem Header <code>If-Match</code> und der <code>version</code> des Eintrags stellt die Entität wieder her (siehe <a href="./diagrams#through-the-api">Diagramme</a>). Die Liste wird nur gelesen und nicht auditiert.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};